// GuardKey.ts
// Per-SKU build settings for the asset guard. GENERATED by `hag keygen --sku demo`; this
// checked-in copy is the sample for SKU "demo" (its private half is published in
// examples/demo-keys/demo-private.json, so a "demo" license proves nothing: make your own
// key for anything you sell).
//
// Nothing in this file is secret: PUB_N / PUB_E are the public half of the seller's RSA key
// and only let a world check that a license was signed by the seller. Policy that must not
// be editable from the editor (grace, keystone, baked license) lives here, in generated
// source, instead of in a prop, so a buyer cannot widen it from the Properties panel.
// `hag keygen` keeps the GRACE_MS / KEYSTONE_* / BAKED_LICENSE values of an existing file.
//
// Blunt reminder (docs/LIMITS.md): a buyer can open this file and swap PUB_N for a key they
// own in two minutes. The signature stops forgery against an UNMODIFIED build only; its
// lasting value is the seller's ledger and `hag trace`.

// Product id. Every license carries it; a license for another SKU is rejected (E14).
export const SKU: string = 'demo';

// RSA-2048 public modulus, big-endian bytes as unpadded base64url (the JWK "n" field).
export const PUB_N: string =
  'tZZ2xhV3cVUOVnzsmZY6SoGAE_luitut56QF0Mgoca5kkyCfip5rvusKyRDxMMrc852HYq7SvgAXnE6eeU4R0ZEM1vF51Dx974z6GrefmxeDGwjCoMv0IN78UFSmHEPjcRbssIkYr2itIjVn5hSB-XBRRbrzbBqiJVX-QIVoz7LfC31dJNZjmGd4KBIY593CZkk3Iyj5FRJwLHPOCOnkdxQrjXWVCFVr7ZhwZsOA0uG9oNzrRO_uUrDB7Qzslz3PRy6G0fYy9mnyKBSgTrhM5ki3F8KAwKlBfcSccK6NpPDUcGQ9iQYLStniRKiJtSadlB4GIMkFRhRsYlAQOar18Q';

// Public exponent as a plain number (65537 default; 3 is the faster seller option).
export const PUB_E: number = 65537;

// Milliseconds a world with NO license stays at tier 0 (full policy) before dropping to
// tier 1. 0 = immediate tier 1. Data is trial either way: without a license there is no key.
export const GRACE_MS: number = 0;

// Seller-owned keystone asset id as a decimal string ('0' = no keystone). Converted with the
// runtime's big-integer constructor only when present (see GuardKeystone.ts).
export const KEYSTONE_ID: string = '0';

// 'off' (default), 'warn' (log only) or 'degrade' (seed-jittered tier 2 after a 3 to 20 min
// delay when the keystone is unauthorized or invalid on every attempt). `hag doctor` refuses
// 'degrade' without a keystone-test record newer than 90 days for this SKU.
export const KEYSTONE_MODE: 'off' | 'warn' | 'degrade' = 'off';

// Optional pre-bound license ('' = none). Used only when the license props are all empty, so
// a buyer whose request code was collected at checkout has zero activation steps.
export const BAKED_LICENSE: string = '';
